package main

import (
	"fmt"
	"math"
)

type Shape interface {
	Area() float64
}

type Circle struct{ Radius float64 }

func (c Circle) Area() float64 { return math.Pi * c.Radius * c.Radius }

type Square struct{ Side float64 }

func (s Square) Area() float64 { return s.Side * s.Side }

func totalArea(shapes []Shape) float64 {
	var sum float64
	for _, s := range shapes {
		sum += s.Area()
	}
	return sum
}

func main() {
	shapes := []Shape{Circle{Radius: 2}, Square{Side: 3}}
	fmt.Printf("%.2f\n", totalArea(shapes))   // 21.57

package main

import (
	"fmt"
	"log"
	"os"
)

// Defined entirely in this package -- *log.Logger's own package never sees this.
type Logger interface {
	Printf(format string, args ...any)
}

func process(logger Logger, orderID string) {
	logger.Printf("processing order %s", orderID)
}

type fakeLogger struct {
	messages []string
}

func (f *fakeLogger) Printf(format string, args ...any) {
	f.messages = append(f.messages, fmt.Sprintf(format, args...))
}

func main() {
	real := log.New(os.Stdout, "", 0)
	process(real, "order-1")   // a real *log.Logger, satisfies Logger with zero coordination

	fake := &fakeLogger{}
	process(fake, "order-2")   // a trivial test double, satisfies the same interface
	fmt.Println(fake.messages) // [processing order order-2]

package main

import "fmt"

type MyError struct{ msg string }

func (e *MyError) Error() string { return e.msg }

func mightFail(shouldFail bool) error {
	var problem *MyError
	if shouldFail {
		problem = &MyError{msg: "it failed"}
	}
	return problem   // always a non-nil error interface, even when problem itself is nil
}

func main() {
	err := mightFail(false)
	fmt.Println(err == nil)   // false -- surprising!
	if err != nil {
		fmt.Println("reported a failure that never actually happened")
	}

