package main

import "fmt"

type Metadata struct {
	CreatedBy string
}

func (m Metadata) Describe() string {
	return "created by " + m.CreatedBy
}

type Document struct {
	Metadata
	Title string
}

func main() {
	doc := Document{
		Metadata: Metadata{CreatedBy: "Amy"},
		Title:    "Q3 Report",
	}

	fmt.Println(doc.CreatedBy)   // Amy -- Metadata's field, promoted onto Document
	fmt.Println(doc.Describe())    // created by Amy -- Metadata's method, promoted onto Document
	fmt.Println(doc.Metadata.CreatedBy)   // Amy -- still reachable explicitly too

package main

import "fmt"

type Animal struct{ Name string }

func (a Animal) Speak() string { return a.Name + " makes a sound" }

type Dog struct {
	Animal
}

func (d Dog) Speak() string {
	return d.Animal.Speak() + " -- specifically, a bark"
}

func main() {
	d := Dog{Animal: Animal{Name: "Rex"}}
	fmt.Println(d.Speak())            // Rex makes a sound -- specifically, a bark

	var a Animal = d.Animal
	fmt.Println(a.Speak())            // Rex makes a sound -- Dog's override never enters the picture

